update pages set contenu = '{"sections":[]}'::jsonb where path = '/secteurs/menuiserie-industrielle/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance en menuiserie industrielle","mecanisme":"Le menuisier connaît le bois, nous connaissons ses machines. Quelques visites bien placées, souvent une par mois, avec le même technicien, valent mieux qu''un programme théorique que personne ne tient.","cta":"Faire visiter mon atelier à un chargé d''affaires","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30, pour un premier contact sur vos priorités."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"+ 100","libelle":"collaborateurs, automaticiens, spécialistes hydraulique et pneumatique, roboticiens"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, taux horaire homogène partout"}]},{"type":"probleme","punchline":"Les grands prestataires regardent ailleurs. Et votre atelier se débrouille seul avec des machines rapides, précises et dangereuses.","puces":[{"accroche":"L''aspiration négligée est le premier signal d''un atelier en danger.","texte":"Qualité en baisse, broches qui chauffent, risque d''incendie qui monte. C''est souvent notre premier chantier chez un nouveau client."},{"accroche":"La poussière de bois encrasse tout.","texte":"Guidages usés, moteurs qui chauffent, accumulation qui s''installe partout où personne ne passe la main."},{"accroche":"Le dixième de millimètre se voit sur le produit fini.","texte":"Plaqueuses de chant, perceuses multibroches, centres d''usinage à commande numérique : le défaut de réglage se retrouve chez le client."},{"accroche":"Une tenonneuse de trente ans cohabite avec un centre connecté.","texte":"Le technicien doit passer de l''une à l''autre et savoir vite ce qui relève du réglage, de l''usure ou de la commande."},{"accroche":"Lames, fers et presses exposent chaque poste.","texte":"Protections et arrêts d''urgence se contrôlent à chaque passage, pas une fois par an."}]}]'::jsonb) where path = '/secteurs/menuiserie-industrielle/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"offre","lignes":[{"prestation":{"accroche":"Préventif minimal efficace","texte":", souvent une visite par mois, avec le même technicien."},"benefice":"Vous sortez du cycle réparer quand ça casse, sans programme théorique impossible à tenir."},{"prestation":{"accroche":"Remise à niveau du réseau d''aspiration","texte":"contrôle des filtres et des débits, reprise de chaudronnerie sur les gaines."},"benefice":"Sécurité incendie, matériel propre, air respirable. C''est la première urgence de la plupart des ateliers."},{"prestation":{"accroche":"Sciage et débit","texte":"scies à panneaux horizontales et verticales, déligneuses, tronçonneuses. Alignements, guidages, freins de lame, protecteurs."},"benefice":"Les coupes reviennent dans la tolérance, et les organes de sécurité redeviennent conformes."},{"prestation":{"accroche":"Usinage du bois","texte":"centres à commande numérique, toupies, moulurières, tenonneuses. Broches, axes, changeurs d''outils, géométrie."},"benefice":"La précision se maintient au lieu de se dégrader jusqu''à la reprise en atelier."},{"prestation":{"accroche":"Placage et assemblage","texte":"plaqueuses de chant, presses à plaquer, cadreuses, perceuses multibroches. Température, colle, pression."},"benefice":"Les réglages qui font la qualité sont suivis et consignés, pas transmis oralement."},{"prestation":{"accroche":"Finition","texte":"ponceuses larges bandes, cabines et lignes de vernissage, séchoirs."},"benefice":"La régularité d''état de surface cesse de dépendre de l''humeur du matériel."},{"prestation":{"accroche":"Flux et manutention","texte":"convoyeurs, retourneurs, empileurs, robots de palettisation, avec nos roboticiens."},"benefice":"La ligne complète est couverte, du débit à la palette, y compris la [maintenance convoyeur](/secteurs/logistique/maintenance-convoyeur/)."},{"prestation":{"accroche":"Historique par équipement","texte":"dans un espace client accessible à votre équipe."},"benefice":"Vos décisions d''investissement s''appuient sur des données réelles, pas sur une impression."},{"prestation":{"texte":"Point suivi"},"benefice":"Ce que vous y gagnez"},{"prestation":{"texte":"Qualité de coupe et d''usinage"},"benefice":"Moins de rebuts, moins de reprises, clients livrés"},{"prestation":{"texte":"État de l''aspiration"},"benefice":"Sécurité incendie, matériel propre, air respirable"},{"prestation":{"texte":"Organes de sécurité"},"benefice":"Conformité, protection des équipes, sérénité en cas de contrôle"},{"prestation":{"texte":"Broches et organes rapides"},"benefice":"Remplacements programmés au lieu de casses subies"},{"prestation":{"texte":"Historique par équipement"},"benefice":"Décisions d''investissement fondées sur des données réelles"},{"prestation":{"texte":"Coût de maintenance"},"benefice":"Un budget lisible, comparé au coût réel des pannes"}],"prose":[{"texte":"Pour les capotages, l''accessibilité des organes et les mises en conformité, notre [bureau d''études](/offres/bureau-etudes/) prépare chaque amélioration en dossier chiffré, réalisable sans arrêter l''atelier plus que nécessaire."}]}]'::jsonb) where path = '/secteurs/menuiserie-industrielle/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"deroule","etapes":[{"titre":"Visite de l''atelier","texte":"identification des équipements critiques, relevé des urgences réelles. Vous recevez une information hiérarchisée, sans catastrophisme commercial."},{"titre":"Traitement des urgences","texte":"l''aspiration en premier dans la majorité des cas, puis les organes de sécurité et les broches."},{"titre":"Préventif minimal","texte":"quelques visites bien placées, avec le même technicien. On commence petit, on prouve, on étend."},{"titre":"Surveillance des points sensibles","texte":"aspiration, broches, sécurités. Trois familles de contrôles réguliers qui évitent l''essentiel des mauvaises surprises."},{"titre":"Dépannage outillé","texte":"diagnostic, intervention documentée, conseil écrit pour éviter la récidive. Chaque passage laisse le parc plus connu qu''avant."},{"titre":"Extension","texte":"le périmètre s''élargit selon l''évolution réelle de votre activité, jamais selon un plan vendu d''avance."}]},{"type":"garanties","puces":[{"accroche":"Un état des lieux hiérarchisé, sans catastrophisme","texte":"ce qui est urgent, ce qui peut attendre, ce qui n''a pas besoin d''être touché. Vous arbitrez sur une liste claire."},{"accroche":"Le même technicien d''une visite à l''autre","texte":"sur un parc mixte et souvent non documenté, la mémoire de l''intervenant vaut autant que sa compétence."},{"accroche":"Un parc qui se documente passage après passage","texte":"fiches machine, historique, conseils écrits. Y compris pour les matériels dont le constructeur a disparu."}]},{"type":"cta","question":"Besoin d''un premier état des lieux honnête sur votre parc bois ?","bouton":"Faire visiter mon atelier à un chargé d''affaires","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Diagnostic sur site et réparation d''un parc machines défaillant chez une PME, sans rachat de matériel neuf","texte":"Lyon, février 2024","lienLibelle":"Étude de cas JOINT LYONNAIS : défaillances machines","lienHref":"/preuves/joint-lyonnais/"},{"titre":"Technicien polyvalent sur un parc hétérogène à forte cadence, papier et emballage","texte":"matière souple, rythme continu","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"},{"titre":"1 à 3 techniciens en renfort des équipes de maintenance sur plusieurs sites de production","texte":"depuis octobre 2024","lienLibelle":"Étude de cas GROUPE ATLANTIC : renfort d''équipes","lienHref":"/preuves/groupe-atlantic/"},{"titre":"Chantiers de montage, déplacements de machines et renfort technique ponctuel, matériaux","texte":"missions documentées","lienLibelle":"Étude de cas SOPREMA : travaux ponctuels","lienHref":"/preuves/soprema/"},{"titre":"Renfort de l''équipe de maintenance pendant les congés d''été","texte":"un technicien sur site, été 2025","lienLibelle":"Étude de cas OGF : arrêt estival","lienHref":"/preuves/ogf-arret-estival/"}]}]'::jsonb) where path = '/secteurs/menuiserie-industrielle/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"objections","questions":[{"question":"Intervenez-vous sur les centres d''usinage à commande numérique bois ?","reponse":"Oui : broches, axes, changeurs d''outils, variateurs, automates. La mécanique de précision et l''électronique de commande relèvent des mêmes expertises que sur le métal, appliquées aux contraintes du bois et de sa poussière."},{"question":"Pouvez-vous remettre à niveau notre réseau d''aspiration ?","reponse":"Oui, et c''est souvent la première urgence : contrôle du réseau, des filtres et des débits, reprise de chaudronnerie sur les gaines, conseil sur les évolutions nécessaires. Une aspiration saine protège le matériel, l''espace de travail et les personnes."},{"question":"Travaillez-vous le samedi ou pendant nos fermetures ?","reponse":"Oui : les opérations lourdes se calent sur vos fermetures, congés ou week-ends, pour ne pas bloquer l''activité. L''astreinte 24/24 et 7/7 existe en option pour les ateliers qui tournent en continu."},{"question":"Notre matériel est ancien et sans documentation. C''est un problème ?","reponse":"Non, c''est notre quotidien. Nous documentons ce que nous découvrons, poste par poste. En quelques visites, votre parc retrouve des fiches utilisables et un historique qui facilite chaque décision, y compris pour rechercher une pièce."},{"question":"Fournissez-vous les pièces détachées ?","reponse":"Nous consultons le marché au prix réel, y compris pour les matériels dont le constructeur a disparu : adaptation, re-fabrication locale, pièces équivalentes. Le stock minimal de pièces critiques se définit ensemble, selon votre rythme de production."},{"question":"Quel est le coût pour un atelier de taille moyenne ?","reponse":"Un état des lieux chiffré d''abord, un devis clair ensuite : taux horaire homogène partout en France, formules à budget prévisible pour l''entretien programmé. La comparaison honnête avec le coût de vos pannes actuelles se fait généralement d''elle-même."}]},{"type":"ctaFinal","question":"Besoin de sortir du système D sur vos machines à bois ?","bouton":"Demander une visite d''atelier","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/secteurs/menuiserie-industrielle/';
